),
inserted_2026 AS (
  INSERT INTO holidays (name, date, year, type, description, is_fixed)
  SELECT s.name, s.date, 2026, s.type, s.description, s.is_fixed
  FROM source_2026 s
  WHERE NOT EXISTS (
    SELECT 1 FROM holidays h
    WHERE h.name = s.name
      AND h.date = s.date
      AND h.year = 2026
      AND h.type = s.type
      AND COALESCE(h.description, '') = COALESCE(s.description, '')
  )
  RETURNING id, name, date, year, type, description
),
target_2026 AS (
  SELECT id, name, date, year, type, description FROM inserted_2026
  UNION ALL
  SELECT h.id, h.name, h.date, h.year, h.type, h.description
  FROM source_2026 s
  JOIN holidays h ON h.name=s.name AND h.date=s.date AND h.year=2026 AND h.type=s.type
    AND COALESCE(h.description, '') = COALESCE(s.description, '')
)
INSERT INTO holiday_locations (holiday_id, location_id)
SELECT DISTINCT h.id, l.id
FROM source_2026 s
JOIN target_2026 h ON h.name=s.name AND h.date=s.date AND h.year=2026 AND h.type=s.type
  AND COALESCE(h.description, '') = COALESCE(s.description, '')
JOIN locations l ON l.code=s.location_code
WHERE NOT EXISTS (
  SELECT 1 FROM holiday_locations hl WHERE hl.holiday_id=h.id AND hl.location_id=l.id
)
ON CONFLICT (holiday_id, location_id) DO NOTHING;

